return $input.all().map(item => {
  // Extrae los metadatos del objeto binary.data
  const binaryData = item.binary?.data || {};

  const fileName = binaryData.fileName || '';
  const directory = binaryData.directory || '';
  const mimeType = binaryData.mimeType || '';
  const fileExtension = binaryData.fileExtension || '';
  const fileSize = binaryData.fileSize || 0;

  // Extrae el nombre del subdirectorio (por ejemplo: "Ingeniero en Sistemas" o "Vendedor punto de venta")
  const basePath = '/home/node/.n8n-files/CVs';
  let relativeFolder = directory.replace(basePath, '').replace(/^\//, '');

  return {
    json: {
      fileName: fileName,
      fileExtension: fileExtension,
      mimeType: mimeType,
      fileSize: fileSize,
      fullPath: `${directory}/${fileName}`,
      directory: directory,
      folderCategory: relativeFolder || 'Raíz', // Categoría basada en el subdirectorio
    },
    // Mantiene los datos binarios intactos por si necesitas extraer el texto del PDF más adelante
    binary: item.binary 
  };
});

const items = $input.all();
const vacantesMap = {};

items.forEach(item => {
  const data = item.json;
  const nombreVacante = data.nombre_vacante;
  const idVacante = data.vacante_id;

  if (!nombreVacante) return;

  // Si no se ha registrado la vacante, se crea la estructura base
  if (!vacantesMap[nombreVacante]) {
    vacantesMap[nombreVacante] = {
      id_vacante: idVacante,
      nombre_vacante: nombreVacante,
      requisitos: []
    };
  }

  // Se añade el requisito al listado de la vacante correspondiente
  vacantesMap[nombreVacante].requisitos.push({
    id_requisito: data.id_requisito,
    nombre: data.nombre,
    descripcion: data.descripcion,
    peso: data.peso,
    obligatorio: data.obligatorio
  });
});

// Convertir el mapa en un arreglo de ítems para n8n
return Object.values(vacantesMap).map(vacante => ({ json: vacante }));

